    ('editorial/look-moss-rust', '/media/editorial/look-moss-rust-2048.webp', 'A model in the Lambswool Cardigan in moss, worn open over the rust Long-Sleeve Henley, in a plaster-walled studio beside a clothing rail', 2048, 1143, 'generated', 'AI-generated stand-in made from the product cut-outs. Replace with a real campaign or studio photograph.', '[{"width":640,"src":"/media/editorial/look-moss-rust-640.webp"},{"width":1080,"src":"/media/editorial/look-moss-rust-1080.webp"},{"width":1600,"src":"/media/editorial/look-moss-rust-1600.webp"},{"width":2048,"src":"/media/editorial/look-moss-rust-2048.webp"}]'::jsonb, '20% 50%'),
    ('editorial/look-oxford-hoodie', '/media/editorial/look-oxford-hoodie-2048.webp', 'A man seated on a wooden bench in the grey marl Fleece Hoodie over the pale blue Oxford Shirt, in a bare, sunlit room', 2048, 1374, 'generated', 'AI-generated stand-in made from the product cut-outs. Replace with a real campaign or studio photograph.', '[{"width":640,"src":"/media/editorial/look-oxford-hoodie-640.webp"},{"width":1080,"src":"/media/editorial/look-oxford-hoodie-1080.webp"},{"width":1600,"src":"/media/editorial/look-oxford-hoodie-1600.webp"},{"width":2048,"src":"/media/editorial/look-oxford-hoodie-2048.webp"}]'::jsonb, '80% 60%'),
    ('editorial/look-stripe-oat', '/media/editorial/look-stripe-oat-1856.webp', 'A model in the Mariner Long Sleeve with the Fleece Crew in oat knotted over her shoulders, against a limestone wall', 1856, 2304, 'generated', 'AI-generated stand-in made from the product cut-outs. Replace with a real campaign or studio photograph.', '[{"width":640,"src":"/media/editorial/look-stripe-oat-640.webp"},{"width":1080,"src":"/media/editorial/look-stripe-oat-1080.webp"},{"width":1600,"src":"/media/editorial/look-stripe-oat-1600.webp"},{"width":1856,"src":"/media/editorial/look-stripe-oat-1856.webp"}]'::jsonb, '38% 40%')
  insert into public.products (id, slug, name, category_id, status, price, summary, description, details, composition, care, fit, fabric, sizes) values
    ('heavyweight-tee', 'heavyweight-tee', 'Heavyweight Tee', 'tops', 'active', 8500, 'Dense 240 gsm jersey with a close, ribbed neck.', 'Our foundation piece. A dense, slightly dry jersey that holds its shape through years of washing, cut straight through the body with a sleeve that ends just above the elbow.', array['240 gsm jersey', 'Ribbed crew neck', 'Straight body']::text[], '100% organic cotton', array['Wash cold, inside out', 'Dry flat in shade', 'Warm iron on reverse']::text[], 'True to size. Take your usual size for a clean fit, one up for a relaxed drape.', 'A compact, long-staple organic cotton knitted tight enough to feel almost dry in the hand. It is garment-dyed and washed before it reaches you, so it keeps its size and its line.', array['XS', 'S', 'M', 'L', 'XL']::text[]),
    ('mariner-long-sleeve', 'mariner-long-sleeve', 'Mariner Long Sleeve', 'tops', 'active', 14000, 'Yarn-dyed ink and bone stripe, cut with a wide boat neck.', 'The stripe is knitted in rather than printed, so it stays sharp. A wide boat neck and a long, narrow sleeve give it the proportions of the original naval shirt.', array['Yarn-dyed stripe', 'Boat neck', 'Long sleeve']::text[], '100% cotton, 220 gsm interlock', array['Wash cold', 'Do not tumble dry', 'Reshape while damp']::text[], 'Slim through the body. Size up if you plan to layer underneath.', 'An interlock cotton with the stripe knitted in from dyed yarn, so the edges stay crisp and never crack or fade the way a print does. Smooth on both faces.', array['XS', 'S', 'M', 'L', 'XL']::text[]),
    ('oxford-shirt', 'oxford-shirt', 'Oxford Shirt', 'shirts', 'active', 18000, 'Washed pale-blue oxford with a soft, unlined button-down collar.', 'A heavy oxford cloth, garment washed so it arrives already broken in. The collar is unlined and rolls rather than lies flat; the single chest pocket is cut on the grain.', array['Button-down collar', 'Single chest pocket', 'Curved hem']::text[], '100% cotton oxford', array['Wash at 30°C', 'Hang to dry', 'Iron while damp']::text[], 'Relaxed. Sleeve length is generous; consider sizing down if between sizes.', 'A heavy oxford woven with a white weft through a pale blue warp, which gives the cloth its soft, broken colour. Washed after sewing for a lived-in hand from the first wear.', array['S', 'M', 'L', 'XL']::text[]),
    ('lambswool-cardigan', 'lambswool-cardigan', 'Lambswool Cardigan', 'knitwear', 'active', 36000, 'Chunky moss lambswool with corozo buttons and deep ribbed trims.', 'Knitted on a coarse gauge for a substantial, lofty hand. The V-neck sits low enough to wear over a shirt; the ribbed cuffs and hem are knitted twice as deep as usual so they keep their grip.', array['5-gauge knit', 'Corozo buttons', 'Deep ribbed trims']::text[], '100% lambswool', array['Hand wash cold', 'Dry flat', 'Fold, never hang, for storage']::text[], 'Relaxed with a dropped shoulder. Take your usual size.', 'Lambswool from the first shearing, spun loosely and knitted on a coarse five-gauge machine. The result is light for its bulk, warm, and slowly softens with each wear.', array['S', 'M', 'L', 'XL']::text[]),
    ('henley', 'henley', 'Long-Sleeve Henley', 'tops', 'active', 12000, 'Slub jersey in rust, with a three-button placket.', 'An irregular slub yarn gives the jersey a faint, uneven texture that softens with wear. Three horn buttons on a short placket; long sleeves finished with a narrow rib.', array['Slub jersey', 'Three-button placket', 'Ribbed cuffs']::text[], '100% cotton', array['Wash cold', 'Dry flat', 'Cool iron']::text[], 'Regular fit, close at the cuff.', 'Slub yarn is spun deliberately uneven, so the jersey carries a faint irregular texture. Garment-dyed in rust, it fades gently and evenly over time.', array['XS', 'S', 'M', 'L', 'XL']::text[]),
    ('fleece-hoodie', 'fleece-hoodie', 'Fleece Hoodie', 'sweats', 'active', 21000, 'Brushed-back 400 gsm fleece in grey marl. No prints, no branding.', 'A heavy loopback fleece, brushed on the inside. The hood is double layered so it holds its shape, with flat cotton drawcords and a single kangaroo pocket.', array['400 gsm fleece', 'Double-layer hood', 'Kangaroo pocket']::text[], '80% cotton, 20% recycled polyester', array['Wash cold, inside out', 'Do not tumble dry']::text[], 'Relaxed through the body, ribbed at the cuff and hem.', 'A 400 gsm loopback fleece, brushed on the reverse for warmth and left smooth outside. The grey marl comes from blending undyed and black fibres before spinning.', array['XS', 'S', 'M', 'L', 'XL']::text[]),
    ('fleece-crew', 'fleece-crew', 'Fleece Crew', 'sweats', 'active', 18500, 'The same heavy fleece as the hoodie, as a clean crewneck in oat.', 'Cut from the hoodie''s 400 gsm loopback fleece with a set-in sleeve and a deep ribbed neck that stays flat. A quieter alternative to knitwear in the colder months.', array['400 gsm fleece', 'Set-in sleeve', 'Ribbed trims']::text[], '80% cotton, 20% recycled polyester', array['Wash cold, inside out', 'Do not tumble dry']::text[], 'Relaxed. Take your usual size.', 'The hoodie''s 400 gsm loopback fleece, dyed a warm undyed-looking oat. Brushed inside, smooth outside, with ribs knitted from the same yarn.', array['XS', 'S', 'M', 'L', 'XL']::text[]),
    ('pique-polo', 'pique-polo', 'Piqué Polo', 'tops', 'active', 13500, 'Bottle-green cotton piqué with a two-button placket.', 'A fine double piqué that is crisp to the touch and breathes in warm weather. The collar is knitted rather than cut, so it keeps its roll.', array['Double piqué', 'Knitted collar', 'Two-button placket']::text[], '100% cotton', array['Wash at 30°C', 'Dry flat']::text[], 'Regular fit, slightly shorter in the body.', 'A double piqué knitted from fine combed cotton: crisp, breathable, with a small honeycomb texture that holds a dyed colour deeply.', array['XS', 'S', 'M', 'L', 'XL']::text[]),
    ('chore-jacket', 'chore-jacket', 'Chore Jacket', 'outerwear', 'active', 24500, 'Washed navy cotton canvas with three patch pockets and horn buttons.', 'The French work jacket, kept plain. A heavy canvas washed until it softens at the edges, with a point collar, five horn buttons and three patch pockets set where hands actually go.', array['12 oz cotton canvas', 'Three patch pockets', 'Horn buttons']::text[], '100% cotton canvas', array['Wash cold, inside out', 'Line dry', 'Expect it to fade gently']::text[], 'Boxy and slightly cropped. Take your usual size to layer a knit underneath.', 'A 12 oz cotton canvas, garment-washed after sewing so the seams pucker slightly and the navy breaks at every edge. It fades the way a pair of jeans does.', array['XS', 'S', 'M', 'L', 'XL']::text[]),
    ('wool-overcoat', 'wool-overcoat', 'Wool Overcoat', 'outerwear', 'active', 62000, 'Double-faced camel wool, cut long, with a soft notch lapel.', 'Two layers of wool woven together and hand-finished at the edges, so the coat needs no lining and falls in one clean line below the knee. Three horn buttons, two flap pockets, nothing else.', array['Double-faced wool', 'Unlined', 'Below-the-knee length']::text[], '90% wool, 10% cashmere', array['Dry clean only', 'Brush after wearing', 'Hang on a shaped hanger']::text[], 'Relaxed through the shoulder, made to go over a knit. Take your usual size.', 'A double-faced camel cloth: two wool faces woven as one, so both sides are finished and the coat is warm without a lining. Hand-felled at every edge.', array['S', 'M', 'L', 'XL']::text[]),
    ('quilted-liner', 'quilted-liner', 'Quilted Liner', 'outerwear', 'active', 28000, 'Diamond-quilted olive nylon with a collarless neck, light enough to wear under a coat.', 'Built as a liner and good enough to wear alone. A matte nylon shell quilted in a fine diamond, a bound collarless neck, snap fastening and two deep patch pockets.', array['Diamond quilting', 'Snap front', 'Bound collarless neck']::text[], 'Shell 100% recycled nylon, fill 100% recycled polyester', array['Machine wash cold', 'Tumble dry low']::text[], 'Close through the body so it layers under the overcoat. Size up to wear over a heavy knit.', 'A matte, peached nylon that doesn''t shine or rustle, stitched through a light recycled fill in a small diamond so the warmth stays evenly spread.', array['XS', 'S', 'M', 'L', 'XL']::text[]),
    ('pleated-trouser', 'pleated-trouser', 'Pleated Wool Trouser', 'trousers', 'active', 23000, 'Charcoal flannel with double pleats, a pressed crease and turn-up hems.', 'A full trouser in a soft winter flannel. Two forward pleats give room through the hip, and the leg tapers gently to a turn-up that holds the crease.', array['Double forward pleats', 'Turn-up hems', 'Side adjusters']::text[], '100% wool flannel', array['Dry clean', 'Steam to refresh the crease', 'Hang by the hem']::text[], 'High rise and full through the thigh. Order your usual waist size.', 'A brushed wool flannel with a soft, slightly fuzzy face. It drapes rather than clings and recovers its crease overnight on a hanger.', array['28', '30', '32', '34', '36']::text[]),
    ('wide-chino', 'wide-chino', 'Wide Chino', 'trousers', 'active', 17500, 'Stone cotton twill with a wide, straight leg and a single pleat.', 'The everyday trouser, cut wider than usual. A dense cotton twill, washed soft, with a single pleat and a straight leg that breaks once on the shoe.', array['Cotton twill', 'Single pleat', 'Straight wide leg']::text[], '100% cotton', array['Wash at 30°C', 'Hang to dry', 'Warm iron']::text[], 'Relaxed and straight. Take your usual waist size.', 'A tightly woven cotton twill, garment-washed for a dry, chalky hand in a stone colour that sits with every top in the collection.', array['28', '30', '32', '34', '36']::text[]),
    ('linen-camp-shirt', 'linen-camp-shirt', 'Linen Camp Shirt', 'shirts', 'active', 16000, 'Washed ecru linen with an open camp collar and a straight hem.', 'A short-sleeved shirt for warm days, cut boxy with an open collar that lies flat. The linen is washed before sewing so it arrives soft and keeps its size.', array['Washed linen', 'Camp collar', 'Straight hem']::text[], '100% linen', array['Wash at 30°C', 'Line dry', 'Wear it creased']::text[], 'Boxy and straight. Take your usual size; it is meant to sit loose.', 'A mid-weight European linen with a visible slub, stone-washed so it is soft from the first wear and creases in an easy, even way.', array['XS', 'S', 'M', 'L', 'XL']::text[]),
    ('merino-crew', 'merino-crew', 'Merino Crew', 'knitwear', 'active', 19500, 'Fine-gauge extra-fine merino, smooth enough to wear against the skin.', 'The knit that goes under everything. A fine 14-gauge merino with a narrow ribbed neck, cuffs and hem, light enough to sit under a jacket and warm enough to wear alone.', array['14-gauge merino', 'Fully fashioned', 'Ribbed trims']::text[], '100% extra-fine merino wool', array['Hand wash cold', 'Dry flat', 'Fold to store']::text[], 'Regular fit, close at the cuff and hem.', 'Extra-fine merino spun to a smooth, matte yarn and knitted fully fashioned, so the seams sit flat and the shape is knitted in rather than cut.', array['XS', 'S', 'M', 'L', 'XL']::text[]),
    ('cashmere-cardigan', 'cashmere-cardigan', 'Cashmere Cardigan', 'knitwear', 'active', 38000, 'Oat cashmere, cut short, with a deep V and mother-of-pearl buttons.', 'A cropped cardigan in a soft, lofty cashmere that ends at the waist, so it works over a dress or a high-rise trouser. Deep ribbed trims and five mother-of-pearl buttons.', array['Two-ply cashmere', 'Cropped length', 'Mother-of-pearl buttons']::text[], '100% cashmere', array['Hand wash cold', 'Dry flat', 'De-pill with a comb']::text[], 'Cropped and relaxed. Take your usual size.', 'Two-ply Mongolian cashmere knitted on a medium gauge and lightly milled, so the surface blooms into a soft halo after the first wash.', array['XS', 'S', 'M', 'L']::text[]),
    ('slip-dress', 'slip-dress', 'Silk Slip Dress', 'dresses', 'active', 34000, 'Sand-washed ecru silk, cut on the bias, with a soft cowl neck.', 'Cut on the bias so it moves with the body rather than hanging from it. A heavy sand-washed silk with a matte, suede-like face, fine adjustable straps and a gentle cowl at the neck.', array['Sand-washed silk', 'Bias cut', 'Adjustable straps']::text[], '100% silk', array['Hand wash cold', 'Dry in shade', 'Cool iron on reverse']::text[], 'Skims the body. Take your usual size; size up for a looser drape.', 'A 22 momme silk charmeuse, sand-washed until the shine softens to a low glow and the hand feels close to suede.', array['XS', 'S', 'M', 'L']::text[]),
    ('rib-knit-dress', 'rib-knit-dress', 'Rib Knit Dress', 'dresses', 'active', 29000, 'A long-sleeved black rib in merino, falling straight to mid-calf.', 'A column of fine rib that holds close without clinging. Long sleeves, a round neck and a straight fall to mid-calf, with short side vents so it walks easily.', array['Fine merino rib', 'Mid-calf length', 'Side vents']::text[], '80% merino wool, 20% polyamide', array['Hand wash cold', 'Dry flat', 'Fold, never hang']::text[], 'Close-fitting with stretch. Take your usual size.', 'Merino plied with a little polyamide and knitted in a narrow 2×2 rib, so the dress recovers its shape after every wear.', array['XS', 'S', 'M', 'L']::text[]),
    ('poplin-shirt-dress', 'poplin-shirt-dress', 'Poplin Shirt Dress', 'dresses', 'active', 26000, 'Crisp white cotton poplin with a point collar and a self-tie belt.', 'The oxford shirt, lengthened. A crisp poplin with a point collar, a single chest pocket and a loose self-tie belt that lets you choose the waist.', array['Cotton poplin', 'Self-tie belt', 'Mid-calf length']::text[], '100% cotton', array['Wash at 40°C', 'Iron while damp']::text[], 'Relaxed. The belt gathers it in; without it, it falls straight.', 'A tightly woven two-ply poplin with a cool, dry hand and a faint sheen that softens with each wash.', array['XS', 'S', 'M', 'L']::text[]),
    ('wide-leg-trouser', 'wide-leg-trouser', 'Wide-Leg Trouser', 'trousers', 'active', 21000, 'Black wool crepe, high in the waist, with a long, fluid wide leg.', 'A high-waisted trouser with two soft pleats and a wide leg that falls to the floor. The crepe has enough weight to swing as you walk and keeps its crease.', array['Wool crepe', 'High waist', 'Two soft pleats']::text[], '96% wool, 4% elastane', array['Dry clean', 'Steam to refresh']::text[], 'High-waisted and full-length. Take your usual size; hem to your shoe.', 'A dry, grainy wool crepe with a touch of stretch, heavy enough to hang straight and soft enough to move.', array['XS', 'S', 'M', 'L']::text[])
